// Python-style repr() helpers, reimplemented from observed behavior.
// Used so that printed structures match CPython's str/repr formatting
// character by character.

// Mimics Python's repr() for a string value.
export function pyReprStr(value) {
  const s = String(value);
  // Python prefers single quotes, but switches to double quotes when the
  // string contains a single quote and no double quote.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

// Mimics Python's repr() for a list of strings, e.g. ['content']
export function pyReprStrList(items) {
  return '[' + items.map(pyReprStr).join(', ') + ']';
}

