// Minimal re-implementation of the argparse behavior used by the source
// script, matching CPython's argparse output (usage/help text, error
// messages and exit codes) as observed from the reference executable.

// Tokens that look like negative numbers are treated as values (the parser
// has no options that look like negative numbers).
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return (
    token.length > 1 && token[0] === '-' && !NEGATIVE_NUMBER.test(token)
  );
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog;
    // -h/--help is implicit, exactly like argparse.
    this._actions = [
      {
        optionStrings: ['-h', '--help'],
        dest: 'help',
        isHelp: true,
        required: false,
        metavar: null,
        help: 'show this help message and exit',
      },
    ];
  }

  add_argument(name, { required = false } = {}) {
    const dest = name.replace(/^--?/, '');
    this._actions.push({
      optionStrings: [name],
      dest,
      isHelp: false,
      required,
      metavar: dest.toUpperCase(),
      help: null,
    });
  }

  _formatActionUsage(action) {
    if (action.isHelp) return '[-h]';
    const part = `${action.optionStrings[0]} ${action.metavar}`;
    return action.required ? part : `[${part}]`;
  }

  format_usage() {
    const parts = this._actions.map((a) => this._formatActionUsage(a));
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  _formatActionInvocation(action) {
    if (action.isHelp) return action.optionStrings.join(', ');
    return `${action.optionStrings[0]} ${action.metavar}`;
  }

  format_help() {
    let out = this.format_usage();
    out += '\noptions:\n';

    const indent = 2;
    const invocations = this._actions.map((a) =>
      this._formatActionInvocation(a)
    );
    // argparse: help_position = min(action_max_length + 2, max_help_position)
    const actionMaxLength = Math.max(
      ...invocations.map((s) => s.length + indent)
    );
    const helpPosition = Math.min(actionMaxLength + 2, 24);

    for (let i = 0; i < this._actions.length; i++) {
      const header = ' '.repeat(indent) + invocations[i];
      const help = this._actions[i].help;
      if (help) {
        out += header.padEnd(helpPosition) + help + '\n';
      } else {
        out += header + '\n';
      }
    }
    return out;
  }

  print_help() {
    process.stdout.write(this.format_help());
  }

  error(message) {
    process.stderr.write(this.format_usage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _matchLongOption(name) {
    // Exact match first, then unambiguous prefix abbreviation
    // (argparse's allow_abbrev=True behavior).
    for (const action of this._actions) {
      if (action.optionStrings.includes(name)) return { action };
    }
    const matches = [];
    for (const action of this._actions) {
      for (const opt of action.optionStrings) {
        if (opt.startsWith('--') && opt.startsWith(name)) {
          matches.push({ action, option: opt });
        }
      }
    }
    if (matches.length === 1) return { action: matches[0].action };
    if (matches.length > 1) {
      return {
        ambiguous: matches.map((m) => m.option),
      };
    }
    return null;
  }

  parse_args(argv) {
    const values = {};
    const seen = new Set();
    const extras = [];
    let onlyPositional = false;

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];

      if (!onlyPositional && token === '--') {
        onlyPositional = true;
        i += 1;
        continue;
      }

      if (!onlyPositional && isOptionLike(token)) {
        if (token.startsWith('--')) {
          const eq = token.indexOf('=');
          const name = eq === -1 ? token : token.slice(0, eq);
          const inlineValue = eq === -1 ? null : token.slice(eq + 1);

          const match = this._matchLongOption(name);
          if (!match) {
            extras.push(token);
            i += 1;
            continue;
          }
          if (match.ambiguous) {
            this.error(
              `ambiguous option: ${name} could match ${match.ambiguous.join(', ')}`
            );
          }
          const action = match.action;

          if (action.isHelp) {
            this.print_help();
            process.exit(0);
          }

          let value;
          if (inlineValue !== null) {
            value = inlineValue;
          } else {
            const next = argv[i + 1];
            if (next !== undefined && !isOptionLike(next)) {
              value = next;
              i += 1;
            } else {
              this.error(
                `argument ${action.optionStrings.join('/')}: expected one argument`
              );
            }
          }
          values[action.dest] = value;
          seen.add(action.dest);
          i += 1;
        } else {
          // Short option(s): only -h exists in this parser.
          const flag = token.slice(0, 2);
          const action = this._actions.find((a) =>
            a.optionStrings.includes(flag)
          );
          if (action && action.isHelp) {
            this.print_help();
            process.exit(0);
          }
          extras.push(token);
          i += 1;
        }
      } else {
        extras.push(token);
        i += 1;
      }
    }

    const missing = this._actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.join(', ')}`
      );
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

