// Re-implementation of the whoosh.fields pieces used by the source script:
// the TEXT field type and the Schema container (black-box, behavior matched
// against the reference executable).
import { pyReprStrList } from './pyrepr.mjs';

// Field type: TEXT(analyzer=analyzer)
export class TEXT {
  constructor({ analyzer = null } = {}) {
    this.analyzer = analyzer;
  }
}

// Schema(content=TEXT(...)) — keyword arguments become named fields.
// Its repr matches whoosh: <Schema: ['content']>
export class Schema {
  constructor(fields = {}) {
    this._fields = { ...fields };
  }

  names() {
    return Object.keys(this._fields);
  }

  toString() {
    return `<Schema: ${pyReprStrList(this.names())}>`;
  }
}

