// Entry point — Node.js port of /workspace/dataset/whoosh/test3.py
import { ArgumentParser } from './lib/argparse.mjs';
import { Schema, TEXT } from './lib/fields.mjs';
import { StemmingAnalyzer } from './lib/analysis.mjs';

// argparse uses os.path.basename(sys.argv[0]) as the program name.
const prog = (process.argv[1] || '').split('/').pop();

const parser = new ArgumentParser({ prog });
parser.add_argument('--a', { required: true });
parser.parse_args(process.argv.slice(2));

const analyzer = new StemmingAnalyzer(); // Create stemming analyzer
const schema = new Schema({ content: new TEXT({ analyzer }) }); // Create schema with custom analyzer
console.log(String(schema));

